import { expect, test } from '../fixtures';

/** A secret the flow was driven with. Set it in the environment or in sova/.env. */
function env(name: string): string {
  const value = process.env[name];
  if (value === undefined) throw new Error(`${name} is not set. Add it to sova/.env or the environment.`);
  return value;
}

// Starts signed out, whatever session the rest of the suite shares.
test.use({ storageState: { cookies: [], origins: [] } });

test('Sign in admin', async ({ page }) => {
  await test.step('Open /auth/login', async () => {
    await page.goto('/auth/login');
  });

  await test.step('Type the admin username', async () => {
    await page.getByRole('textbox', { name: 'Username or Email address', exact: true }).fill(env('APP_ADMIN_USER'));
  });

  await test.step('Type the admin password', async () => {
    await page.getByRole('textbox', { name: 'Password', exact: true }).fill(env('APP_ADMIN_PASSWORD'));
  });

  await test.step('Press Login', async () => {
    await page.getByRole('button', { name: 'Login', exact: true }).click();
  });

  await test.step('Open the admin overview', async () => {
    await page.goto('/admin/');
  });

  await test.step('The management overview is shown to the admin [code]', async () => {
    await expect(page.getByRole('heading', { name: 'Everything seems alright.', exact: true })).toBeVisible();
  });

  await test.step('Keep the signed-in session for the other tests', async () => {
    await page.context().storageState({ path: process.env.SOVA_AUTH_STATE_ADMIN!, indexedDB: true });
  });
});
